def _guard_admission(method):
    """Admit only this exact current wrapper's captured reflected delegation."""
    report = {}; raw = None
    try:
        helper = getattr(getattr(unreal, 'CubelessBlueprintNiagaraTemplateSwapAttachmentLibrary', None), 'verify_blueprint_niagara_template_swap_toolset', None)
        if not callable(helper):
            raise RuntimeError('Exact BlueprintNiagaraTemplateSwap adapter raw-input admission helper is unavailable')
        raw = helper(CubelessBlueprintNiagaraTemplateSwapTools)
        report = json.loads(raw)
        if (type(report) is dict and report.get('operation') == 'verify_blueprint_niagara_template_swap_toolset'
                and report.get('delegated_call_admitted') is True and report.get('delegated_admission_only') is True
                and report.get('delegated_method') == method
                and report.get('asset_mutation') is False and report.get('metadata_mutation') is False):
            return None, report, raw
        message = 'Canonical guarded BlueprintNiagaraTemplateSwap adapter delegation is required; no Native operation was dispatched'
    except Exception as admission_error:
        message = str(admission_error)
    result = domain._rejected(method,domain.OperationError('blueprint_niagara_template_swap_raw_guard_admission_missing', message))
    result['stage'] = 'blueprint_niagara_template_swap_registration_admission'
    result['data'].update(registration_guard=report, registration_guard_raw=raw,
        native_dispatched=False, python_dispatched=True, journal_created=False,
        helper_receipt_is_whole_SDK_change_proof=False)
    return result, report, raw


def _invalid_constant(value):raise ValueError('Non-finite JSON not supported: '+value)

def _decode_value(text):
    if type(text) is not str or len(text.encode('utf-16-le'))//2>1048576 or '\x00' in text:raise ValueError('Bounded private JSON value carrier required')
    return json.loads(text,parse_constant=_invalid_constant)

def _carrier_rejected(method,error,report,raw):
    result=domain._rejected(method,domain.OperationError('blueprint_niagara_template_swap_registration_carrier_invalid',str(error)))
    result['stage']='blueprint_niagara_template_swap_registration_carrier_admission';result['data'].update(registration_guard=report,registration_guard_raw=raw,native_dispatched=False,python_dispatched=True,journal_created=False)
    return result
